        if(!项.引用内容条件)return;
        const auto& 内容=*项.引用内容条件;
        要求(项.参数序号&&!有效(项.参数角色节点)&&!项.任务成员变量序号
            &&!项.存在概念节点&&!项.特征类型概念节点&&!项.特征值域概念节点
            &&!项.二次特征概念节点&&!项.状态或动态概念节点&&!项.精确数值域
            &&有效(内容.要求概念节点)&&内容.正式内容路径.size()<=1,"非法内容条件副本");
